/* ----------------------------------------------------
   外部 Mod 记忆区与嵌套折叠面板全端终极对齐体系 (彻底根除 600px 虚空黑洞)
   ---------------------------------------------------- */
/* 1. 凡是嵌套折叠面板(如星记忆回廊/星记忆区/星记忆配置)及包含表格的折叠块，全量强制恢复 white-space: normal 并重置 min-height */
#customized-answer-content details details,
#customized-answer-content details details *,
#customized-answer-content details:has(table),
#customized-answer-content details:has(table) *,
#customized-answer-content details div:has(> table),
#customized-answer-content details div:has(> table) *,
#customized-answer-content details table,
#customized-answer-content details table *,
#customized-answer-content details pre,
#customized-answer-content details pre * {
  white-space: normal !important;
  min-height: 0 !important;
}

/* 2. 外部 Mod 内部段落与散装文本容器微排版 */
#customized-answer-content details p {
  white-space: normal !important;
  margin: 4px 0 !important;
  line-height: 1.6 !important;
}

/* 3. 彻底清除嵌套折叠块及表格容器内所有子元素累加外边距与虚高内边距 */
#customized-answer-content details details[open] > *:not(summary),
#customized-answer-content details:has(table)[open] > *:not(summary) {
  margin: 2px 0 !important;
  padding: 0 10px !important;
}

/* 4. 彻底歼灭嵌套折叠块与记忆区内的所有空标签、空段落、空行与空 div */
#customized-answer-content details p:empty,
#customized-answer-content details p:has(> br:only-child),
#customized-answer-content details br + br,
#customized-answer-content details details p:empty,
#customized-answer-content details details div:empty,
#customized-answer-content details details *:empty:not(hr):not(th):not(td):not(tr),
#customized-answer-content details:has(table) p:empty,
#customized-answer-content details:has(table) div:empty,
#customized-answer-content details:has(table) *:empty:not(hr):not(th):not(td):not(tr) {
  display: none !important;
  height: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 5. 短期/长期记忆区标题标签紧凑微排版 (⚜️ [STM] / ⚜️ [LTM]) */
#customized-answer-content details details p,
#customized-answer-content details details div,
#customized-answer-content details:has(table) p,
#customized-answer-content details:has(table) div {
  margin: 4px 0 !important;
  padding: 0 !important;
  line-height: 1.5 !important;
}

/* 6. 数据表格贴顶对齐与边距收敛 */
#customized-answer-content details table,
#customized-answer-content details div:has(> table) {
  margin-top: 4px !important;
  margin-bottom: 8px !important;
  padding: 0 !important;
}
